package main

import (
	"bufio"
	"fmt"
	"os"
)

type Matrix [][]int64

func multiply(a, b Matrix) Matrix {
	n := len(a)
	c := make(Matrix, n)
	for i := range c {
		c[i] = make([]int64, n)
	}

	for i := 0; i < n; i++ {
		for k := 0; k < n; k++ {
			if a[i][k] == 0 {
				continue
			}
			for j := 0; j < n; j++ {
				c[i][j] += a[i][k] * b[k][j]
			}
		}
	}
	return c
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s string
	fmt.Fscan(in, &n)
	fmt.Fscan(in, &s)

	m := len(s)
	pi := make([]int, m)
	for i := 1; i < m; i++ {
		j := pi[i-1]
		for j > 0 && s[i] != s[j] {
			j = pi[j-1]
		}
		if s[i] == s[j] {
			j++
		}
		pi[i] = j
	}

	transitions := make(Matrix, m)
	for i := range transitions {
		transitions[i] = make([]int64, m)
	}

	for state := 0; state < m; state++ {
		for _, ch := range []byte{'0', '1'} {
			next := state
			for next > 0 && s[next] != ch {
				next = pi[next-1]
			}
			if s[next] == ch {
				next++
			}
			if next < m {
				transitions[state][next]++
			}
		}
	}

	power := make(Matrix, m)
	for i := range power {
		power[i] = make([]int64, m)
		power[i][i] = 1
	}

	for i := 0; i < n; i++ {
		power = multiply(power, transitions)
	}

	var avoiding int64
	for i := 0; i < m; i++ {
		avoiding += power[i][i]
	}

	total := int64(1) << n
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, total-avoiding)
}

